import Header from './components/Header'
import './App.css';
import background from './images/bg.jpg'
import 'bootstrap/dist/css/bootstrap.min.css';
import { Container } from 'react-bootstrap';

function App() {
  return (
    <Container className='bg' style={{backgroundColor: '#3C413E'}}>
      <div className='bg_image' style={{backgroundImage: `url(${background})`, backgroundRepeat: 'no-repeat', backgroundPosition: 'center', backgroundSize: 'cover', width: '70vw', height: '100vh', borderTopRightRadius: '10%',borderBottomRightRadius: '10%', opacity: 0.3}}>
        <div className='bg_content' style={{ backdropFilter: 'blur(5px)', position: 'relative', top: 50, right: 100,fontSize: 60, textAlign: 'right', color: '#0F0404'}}> Connect with Your co-passengers</div>
      </div>
    </Container>
  )
}
export default App;
